class Site:
    def __init__(self) -> None:
        self.requests: list[httpx.Request] = []
        self.forced: list[Reply] = []
        self.ads: dict[str, dict[str, Any]] = {"5001": dict(AD)}

    def force(self, *replies: Reply) -> Site:
        self.forced.extend(replies)
        return self

    def __call__(self, request: httpx.Request) -> httpx.Response:
        self.requests.append(request)
        if self.forced:
            reply = self.forced.pop(0)
            if isinstance(reply, Exception):
                raise reply
            return reply(request) if callable(reply) else reply
        if request.url.host == "api.digit-u.id":
            return self.login(request)
        if request.url.host == "photos.tap.az":
            return self.photos(request)
        return self.graphql(request)

    def login(self, request: httpx.Request) -> httpx.Response:
        body = json.loads(request.content)
        if request.url.path == "/auth":
            if body["phone"] == "0991112233":
                return httpx.Response(422, json={"error": "code_requests", "message": "Limit"})
            return httpx.Response(200, json={"code_requests_left": 2})
        if body["code"] != "1234":
            return httpx.Response(422, json={"error": "code", "message": "Wrong code"})
        return httpx.Response(200, json={"access_token": "digitu-token", "redirect_url": "https://tap.az/"})

    def photos(self, request: httpx.Request) -> httpx.Response:
        if request.headers.get("cookie") != SESSION:
            return httpx.Response(401, json={"error": "unauthorized"})
        if request.url.path == "/pond/rotate":
            return httpx.Response(200, json={"id": "tap/r.jpg", "thumbnail_url": "https://tap.azstatic.com/t/r.jpg"})
        return httpx.Response(200, json={"photos": [{"id": "tap/2026/11/06/x.jpg",
                                                     "thumbnail_url": "https://tap.azstatic.com/t/x.jpg"}]})

    def graphql(self, request: httpx.Request) -> httpx.Response:
        body = json.loads(request.content)
        op, v = body.get("operationName"), body.get("variables") or {}
        authed = request.headers.get("cookie") == SESSION
        ok = lambda d: httpx.Response(200, json={"data": d})
        if op == "LoginUser":
            if v.get("accessToken") == "digitu-token":
                return httpx.Response(200, json={"data": {"loginUser": {"entity": gid("User", 7), "errors": []}}},
                                      headers=[("set-cookie", f"{SESSION}; path=/; secure; HttpOnly"),
                                               ("set-cookie", "__cf_bm=cf; path=/")])
            return ok({"loginUser": {"entity": None, "errors": [{"code": "invalid", "message": "Token", "path": []}]}})
        if op == "Category":
            if v["id"] == gid("Category", 635):
                return ok({"node": CATEGORY})
            if v["id"] == gid("Category", 606):
                return ok({"node": {**CATEGORY, "legacyResourceId": "606", "hasChildren": True, "properties": []}})
            return ok({"node": None})
        if op == "PropertyOptions":
            options = {"3724": [{"legacyResourceId": "38046", "name": "Monthly", "parentLegacyId": "3724",
                                 "hasChildren": False, "childrenPropertyIds": [], "propertyLegacyId": "994"}]}
            return ok({"propertyOptions": options.get(v["p"], [])})
        if op == "Categories":
            plain = {k: CATEGORY[k] for k in CATEGORY if k != "properties"}
            return ok({"categories": [{**plain, "legacyResourceId": "606", "name": "Real estate", "hasChildren": True,
                                       "children": [plain]}]})
        if op == "Regions":
            return ok({"regions": [{"legacyResourceId": 420, "name": "Baku", "default": True}]})
        if op == "ContactTypes":
            return ok({"formElements": {"contactTypes": [{"enum": "CALLS_AND_MESSAGES", "name": "Calls and messages",
                                                          "default": True}]}})
        if op == "CurrentUser":
            return ok({"currentUser": USER if authed else {k: None for k in USER}})
        if not authed:
            return httpx.Response(200, json={"data": {}, "errors": [
                {"message": "You are not authorized to perform this action", "extensions": {"code": "UNAUTHORIZED"}}]})
        if op == "CreateAd":
            p = v["p"]
            if p.get("price") == 1.0:
                return ok({"createAd": {"entity": None, "errors": [
                    {"code": "VALIDATION_ERROR", "message": "is too low", "path": ["price"], "extensions": None}]}})
            ad = {**AD, "id": gid("Ad", 5002), "legacyResourceId": 5002, "status": "PENDING",
                  "path": "/elanlar/dasinmaz-emlak/menziller/5002"}
            self.ads["5002"] = ad
            return ok({"createAd": {"entity": ad, "errors": []}})
        if op == "UpdateAd":
            return ok({"updateAd": {"entity": self.ads["5001"], "errors": []}})
        if op == "DeleteReasons":
            return ok({"ad": {"deleteReasons": [
                {"id": gid("DeleteReason", 4), "name": "Sold on tap.az", "descriptionRequired": False},
                {"id": gid("DeleteReason", 6), "name": "No longer selling", "descriptionRequired": False},
                {"id": gid("DeleteReason", 20), "name": "Other", "descriptionRequired": True}]}})
        if op in ("DestroyAd", "ProlongAds"):
            field = {"DestroyAd": "destroyAd", "ProlongAds": "prolongAds"}[op]
            return ok({field: {"entity": True, "errors": []}})
        if op == "Ad":
            ad = self.ads.get(v["id"])
            if not ad:
                return httpx.Response(200, json={"data": None, "errors": [{"message": "Record not found"}]})
            return ok({"ad": ad})
        if op == "MyAds":
            nodes = list(self.ads.values())
            more = v.get("after") is None and v.get("first") == 1
            return ok({"currentUserAds": {"totalCount": len(nodes),
                                          "pageInfo": {"hasNextPage": more, "endCursor": "c1" if more else None},
                                          "nodes": nodes[:1] if v.get("first") == 1 and not v.get("after")
                                          else nodes[1:] if v.get("after") else nodes}})
        return httpx.Response(400, json={"errors": [{"message": f"unknown operation {op}"}]})

    def ops(self) -> list[str]:
        out = []
        for r in self.requests:
            if r.url.host == "tap.az":
                out.append(str(json.loads(r.content).get("operationName")))
            else:
                out.append(f"{r.url.host}{r.url.path}")
        return out

    def last(self, operation: str) -> dict[str, Any]:
        for r in reversed(self.requests):
            if r.url.host == "tap.az" and json.loads(r.content).get("operationName") == operation:
                return dict(json.loads(r.content))
        raise AssertionError(operation)


def _quiet(client: Any) -> Any:
    client._backoff = lambda attempt: 0.0
    client._sleep = (lambda seconds: None) if isinstance(client, TapAz) else _no_wait
    return client


async def _no_wait(seconds: float) -> None:
    return None


